# G38: Deploy ALL 34 .zig files + build.zig (ALL fixes applied)
# This deploys EVERY core/*.zig file with ALL Zig 0.13 compatibility fixes.
$ErrorActionPreference = 'Continue'
$DeployRoot = $PSScriptRoot
if (-not $DeployRoot) { $DeployRoot = (Get-Location).Path }

function DF {
    param([string]$T,[string]$B,[string]$L)
    Write-Host ('  [D] ' + $L)
    $p = Split-Path $T -Parent
    if (-not (Test-Path $p)) { New-Item -ItemType Directory -Force -Path $p | Out-Null }
    $b = [System.Convert]::FromBase64String($B)
    [System.IO.File]::WriteAllBytes($T, $b)
}

Write-Host '[G38] Deploying ALL files...' -ForegroundColor Cyan

