'@ -replace "`r`n", "" -replace "`n", ""
DF -T (Join-Path $DeployRoot 'core\\xdr_harden_integration.zig') -B $b64_core_xdr_harden_integration_zig -L 'FIX: xdr_harden_integration.zig'

Write-Host ''
Write-Host '[BUILD]' -ForegroundColor Cyan
& zig build 2>&1 | Out-Host
if ($LASTEXITCODE -eq 0 -and (Test-Path 'zig-out\bin\aegis-nids.exe')) {
    Write-Host ('[SUCCESS] ' + (Get-Item 'zig-out\bin\aegis-nids.exe').Length + ' bytes') -ForegroundColor Green
} else {
    Write-Host '[FAILED]' -ForegroundColor Red
}
Write-Host ''
Write-Host '[TEST]' -ForegroundColor Cyan
& zig build test 2>&1 | Out-Host
Write-Host ''
Write-Host '=== G38 COMPLETE ===' -ForegroundColor Green
Write-Host 'Run: zig build run'